import { useState } from 'react';
import { JxButton, JxDrawer, JxDivider } from '@jinx-ui/react';

type NavKey = 'projects' | 'team' | 'settings' | 'logout';

const ITEMS: { key: NavKey; label: string }[] = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export interface NavMenuProps {
  onNavigate: (key: NavKey) => void;
}

export default function NavMenu({ onNavigate }: NavMenuProps) {
  const [open, setOpen] = useState(false);

  const select = (key: NavKey) => {
    onNavigate(key);
    setOpen(false);
  };

  return (
    <>
      <JxButton variant="primary" onClick={() => setOpen(true)}>
        Меню
      </JxButton>

      <JxDrawer open={open} onOpenChange={setOpen} side="left" title="Навигация">
        <nav
          aria-label="Основная навигация"
          style={{
            display: 'flex',
            flexDirection: 'column',
            gap: 'var(--jx-space-2)',
            padding: 'var(--jx-space-3)',
          }}
        >
          {ITEMS.map((item) => (
            <JxButton
              key={item.key}
              variant="ghost"
              style={{ justifyContent: 'flex-start', width: '100%' }}
              onClick={() => select(item.key)}
            >
              {item.label}
            </JxButton>
          ))}

          <JxDivider />

          <JxButton
            variant="danger"
            style={{ justifyContent: 'flex-start', width: '100%' }}
            onClick={() => select('logout')}
          >
            Выйти
          </JxButton>
        </nav>
      </JxDrawer>
    </>
  );
}

